+function actionText(action: LrStepInfo["action"]): string {
+  switch (action.kind) {
+    case "shift":
+      return `shift ${action.terminal} ${JSON.stringify(action.lexeme)}`;
+    case "reduce":
+      return `reduce ${action.lhs} → ${action.rhs.join(" ")} (pop ${action.rhs.length}, goto ${action.lhs})`;
+    case "accept":
+      return "accept";
+  }
+}
